const items = $input.all();
let successfulFeeds = 0;
let articlesSeen = 0;
for (const item of items) {
  const payload = item.json?.body ?? item.json?.data ?? item.json;
  const xml = typeof payload === 'string' ? payload : payload?.body ?? payload?.data ?? '';
  if (typeof xml !== 'string' || !xml.trim()) continue;
  successfulFeeds += 1;
  articlesSeen += (xml.match(/<(?:item|entry)\b/gi) || []).length;
}
return [{ json: { scanId: `n8n-${Date.now()}`, status: successfulFeeds > 0 ? 'SUCCESS' : 'ERROR', scannedAt: new Date().toISOString(), source: 'n8n_google_news', articlesSeen, queriesRun: items.length } }];

const ENERGY = /\b(?:crude oil|oil exports?|oil imports?|oil tanker|tankers?|refiner(?:y|ies)|pipelines?|oilfield|oil terminal|oil flows?|barrels?|petroleum|opec|lng|lpg|fuel shipment|export route|shipping lane)\b/i;
const TRANSIT = /strait of hormuz|persian gulf|red sea|suez/i;
const THREAT = /\b(?:sanction(?:s|ed)?|embargo|disrupt(?:ion|ed)?|attack(?:ed)?|strike|conflict|war|tension|blockade|closure|outage|shutdown|seiz(?:e|ed|ure)|military|missile|drone|geopolitical|restriction|shortage|supply cut|production cut|reroute|avoid|alternative route|flows? stall(?:ed)?|halt(?:ed)?|hit|pirat(?:e|es)|fire|warning|alert|risk)\b/i;

function decode(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/\s+/g, ' ').trim();
}

function field(block, tag) {
  const match = block.match(new RegExp('<' + tag + '[^>]*>([^]*?)</' + tag + '>', 'i'));
  return match ? decode(match[1]) : '';
}

function link(block) {
  const atom = block.match(/<link\b[^>]*href=[\"']([^\"']+)[\"']/i);
  if (atom) return decode(atom[1]);
  return field(block, 'link');
}

function canonicalUrl(value) {
  try {
    const url = new URL(value);
    for (const key of [...url.searchParams.keys()]) {
      if (/^(?:utm_|oc$|ved$|usg$|ref$|source$|cmpid$)/i.test(key)) url.searchParams.delete(key);
    }
    url.hash = '';
    return url.toString();
  } catch {
    return value;
  }
}

function stableId(value) {
  let hash = 2166136261;
  for (const character of value) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return `n8n-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

const output = [];
const seen = new Set();
for (const item of $input.all()) {
  const payload = item.json?.body ?? item.json?.data ?? item.json;
  const xml = typeof payload === 'string' ? payload : payload?.body ?? payload?.data ?? '';
  if (typeof xml !== 'string' || !xml.trim()) continue;
  const blocks = [
    ...(xml.match(/<item\b[\s\S]*?<\/item>/gi) || []),
    ...(xml.match(/<entry\b[\s\S]*?<\/entry>/gi) || [])
  ];
  for (const block of blocks) {
    const title = field(block, 'title');
    const sourceUrl = link(block);
    const source = field(block, 'source') || 'Google News';
    const description = field(block, 'description') || field(block, 'summary') || title;
    const publishedRaw = field(block, 'pubDate') || field(block, 'published') || field(block, 'updated');
    const timestamp = Date.parse(publishedRaw);
    const publishedAt = Number.isNaN(timestamp) ? undefined : new Date(timestamp).toISOString();
    const text = `${title} ${description}`;
    if (!title || !sourceUrl || !((ENERGY.test(text) || TRANSIT.test(text)) && THREAT.test(text))) continue;
    const identity = `${canonicalUrl(sourceUrl)}\n${title.toLowerCase().replace(/\s+/g, ' ').trim()}`;
    if (seen.has(identity)) continue;
    seen.add(identity);
    output.push({
      json: {
        id: stableId(identity),
        title,
        source,
        sourceUrl,
        description,
        ...(publishedAt ? { publishedAt } : {}),
        retrievedAt: new Date().toISOString(),
        sourceType: 'n8n_google_news',
        query: item.json?.query,
        feedUrl: item.json?.feedUrl
      }
    });
  }
}
return output;
